from services.calculations.debt import AvalancheCalculator, SnowballCalculator, Simulator
from typing import Dict

class DebtSpecialist:
    def __init__(self, llm_client):
        self.llm_client = llm_client
        self.calculators = {
            'avalanche': AvalancheCalculator(),
            'snowball': SnowballCalculator()
        }

    def get_action_reason_learn(self, debt_data: Dict) -> Dict:
        total_outstanding = sum(debt['outstanding'] for debt in debt_data)
        highest_interest = max(debt['interest_rate'] for debt in debt_data)
        next_emi = min(debt['next_emi'] for debt in debt_data)

        if total_outstanding == 0:
            action = 'No debt to pay off'
            reason = 'All debts are already paid off.'
            learn = 'Congratulations! You have no debt to manage.'
        elif highest_interest > 0:
            action = 'Avalanche Method'
            reason = 'High-interest debt should be paid off first.'
            learn = 'The Avalanche Method targets debts with the highest interest rates first.'
        else:
            action = 'Snowball Method'
            reason = 'Low-interest debt should be paid off first.'
            learn = 'The Snowball Method targets debts with the smallest balances first.'

        return {
            'action': action,
            'reason': reason,
            'learn': self.llm_client.generate_text(action, reason, learn)
        }
